"""Arithmetic mean over recorded finite numeric observations.

Definition source (single public technical reference):
    NIST/SEMATECH e-Handbook of Statistical Methods, section 1.3.5.1
    "Measures of Location": "mean - the mean is the sum of the data points
    divided by the number of data points."
    https://www.itl.nist.gov/div898/handbook/eda/section3/eda351.htm

Scope, kept deliberately narrow: this tool returns the arithmetic mean and the
three record-level denominators that decide which records the mean was taken
over. It computes no dispersion, no interval, no test and no model. A missing
value is never read as 0 and never enters the sum; a recorded 0 is a known
observation and is retained.
"""

import math

#: Input shapes or values this tool refuses, with the reason it refuses them.
REFUSAL_REASONS = {
    "empty_original": "原始记录数为 0：没有任何记录可供计算，拒绝返回均值。",
    "empty_known": "已知值数为 0：全部记录都不含有限数值观测，分母为 0，拒绝返回均值。",
    "observations_not_list": "观测集不是序列：无法逐条判定可用值。",
    "record_not_object": "记录不是对象：无法读取其取数字段。",
    "record_missing_value_field": "记录缺少取数字段：无法判定该记录是否为已知观测。",
    "value_boolean": "记录取数为布尔值：布尔值不是数值观测，不计入已知值，也不计为缺失。",
    "value_nonfinite": "记录取数为非有限数（NaN 或无穷）：非有限值不是可记录的观测，不计入已知值。",
    "value_not_numeric": "记录取数既不是有限数值也不是缺失标记：类型不属于已知值或缺失两类。",
}


def _is_missing(value):
    return value is None


def _classify(record, index):
    """Return ('known', float(value)) or ('missing', None); raise ValueError otherwise."""
    if not isinstance(record, dict):
        raise ValueError(REFUSAL_REASONS["record_not_object"])
    if "value" not in record:
        raise ValueError(REFUSAL_REASONS["record_missing_value_field"])
    value = record["value"]
    if _is_missing(value):
        return "missing", None
    if isinstance(value, bool):
        raise ValueError(REFUSAL_REASONS["value_boolean"])
    if isinstance(value, int) or isinstance(value, float):
        number = float(value)
        if not math.isfinite(number):
            raise ValueError(REFUSAL_REASONS["value_nonfinite"])
        return "known", number
    raise ValueError(REFUSAL_REASONS["value_not_numeric"])


def _accepted(mean, summary, known, missing, original, total):
    return {
        "status": "accepted",
        "mean": mean,
        "sum": summary,
        "original": original,
        "known": known,
        "missing": missing,
        "total": total,
        "method": "arithmetic_mean_over_recorded_finite_values",
    }


def _rejected(reason):
    return {
        "status": "rejected",
        "reason": reason,
        "mean": None,
        "sum": None,
        "original": None,
        "known": None,
        "missing": None,
        "total": None,
        "method": "arithmetic_mean_over_recorded_finite_values",
    }


def mean_known(specification):
    """Mean over recorded finite numeric observations, with three denominators.

    specification: {"observations": [{"value": <finite number | None>}, ...]}

    Returns {"status", "mean", "sum", "original", "known", "missing", "total",
    "method"} with:
      original — records supplied;
      known    — records whose value is a finite number and so entered the sum;
      missing  — records whose value is a null placeholder (never read as 0).
    known + missing == original. An empty input, an all-missing input, a boolean
    value or a non-finite value is refused rather than silently coerced.
    """
    if not isinstance(specification, dict):
        return _rejected(REFUSAL_REASONS["observations_not_list"])
    observations = specification.get("observations")
    if isinstance(observations, (str, bytes, dict)) or observations is None:
        return _rejected(REFUSAL_REASONS["observations_not_list"])
    try:
        records = list(observations)
    except TypeError:
        return _rejected(REFUSAL_REASONS["observations_not_list"])

    original = len(records)
    if original == 0:
        return _rejected(REFUSAL_REASONS["empty_original"])

    known = 0
    missing = 0
    total = 0.0
    for index, record in enumerate(records):
        try:
            kind, number = _classify(record, index)
        except ValueError as error:
            return _rejected(str(error))
        if kind == "known":
            known += 1
            total += number
        else:
            missing += 1

    if known == 0:
        return _rejected(REFUSAL_REASONS["empty_known"])

    mean = total / known
    return _accepted(mean, total, known, missing, original, original)


if __name__ == "__main__":
    self_call = mean_known({"observations": [{"value": 1}, {"value": 2}, {"value": 3}]})
    print("self-call:", self_call["mean"], self_call["known"], self_call["missing"], self_call["status"])
    with_missing = mean_known({"observations": [{"value": 1}, {"value": None}, {"value": 3}]})
    print("with missing:", with_missing["mean"], with_missing["known"], with_missing["missing"])
    with_zero = mean_known({"observations": [{"value": 0}, {"value": None}, {"value": 2}]})
    print("zero retained:", with_zero["mean"], with_zero["known"], with_zero["missing"])
    refused = mean_known({"observations": [{"value": True}]})
    print("boolean refused:", refused["status"], refused["reason"])

"""Static self-check over the candidate tool files.

Reports any occurrence of the forbidden modules and dynamic constructs that the
candidate rules exclude. Run over scripts/ and tests/ only; it is a checker for
the candidate, not part of the candidate.
"""

import os

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.dirname(HERE)

FORBIDDEN_MODULES = [
    "requests", "httpx", "urllib", "socket", "subprocess", "importlib",
    "ctypes", "multiprocessing", "pickle", "marshal", "runpy",
]

FORBIDDEN_CALLS = [
    "eval(", "exec(", "compile(", "__import__", "globals(", "locals(",
    "sys.exit", "os._exit",
]

FORBIDDEN_MEMBER_CALLS = ["getattr(", "setattr(", "delattr(", "vars("]


def scan(path):
    findings = []
    with open(path, encoding="utf-8") as handle:
        lines = handle.read().splitlines()
    for number, line in enumerate(lines, start=1):
        stripped = line.strip()
        for module in FORBIDDEN_MODULES:
            if ("import " + module) in line or ("from " + module) in line:
                findings.append((number, "module:" + module, stripped))
        for token in FORBIDDEN_CALLS + FORBIDDEN_MEMBER_CALLS:
            if token in line:
                findings.append((number, "call:" + token, stripped))
    return findings


def main():
    targets = []
    for relative in ("scripts", "tests"):
        directory = os.path.join(ROOT, relative)
        for name in sorted(os.listdir(directory)):
            if name.endswith(".py"):
                targets.append(os.path.join(directory, name))
    total = 0
    for path in targets:
        findings = scan(path)
        total += len(findings)
        print(os.path.relpath(path, ROOT), "findings=", len(findings))
        for number, token, line in findings:
            print("  line", number, token, "->", line)
    print("files_scanned=", len(targets))
    print("findings_total=", total)
    return 1 if total else 0


if __name__ == "__main__":
    raise SystemExit(main())

